style.css:
@-moz-document url-prefix("https://chat.openai.com/") {
html, body {
    background: radial-gradient(circle at 20% 30%, #ff7eb3 0%, transparent 60%),
                radial-gradient(circle at 80% 70%, #65d6ce 0%, transparent 60%),
                radial-gradient(circle at 50% 50%, #fce38a 0%, transparent 70%);
    background-color: #0b0b0b;
    background-attachment: fixed;
    background-size: cover;
  }

  /* خلي اللوحات شفافة علشان الخلفية تبان */
  .main,
  [class*="conversation"],
  [class*="scrollable"],
  [class*="flex-1"],
  [class*="overflow"],
  [class*="bg-token"],
  [class*="bg-layer"],
  .text-base,
  .prose,
  .message {
    background: transparent !important;
    background-color: transparent !important;
    backdrop-filter: none !important;
  }

  /* لو عايز نص أو ألوان تكون مقروءة */
  .chat, .content, .markdown {
    color: #ddd !important;
  }
}
